	statevars {
		int buffer[10];
		int head;
		int tail;
		int size;
	}
	Consumer() {
		head = 0;
		tail = 0;
		size = 0;
	}
	msgsrv initial() {
		// No automatic behavior
	}
	msgsrv ItemMsg(int dataId) {
		// enqueue dataId into circular buffer if not full
		if (size < 10) {
			buffer[tail] = dataId;
			tail = (tail + 1) % 10;
			size = size + 1;
		} else {
			// buffer full, drop item (no-op)
		}
	}
	msgsrv ConsumeMsg() {
		if (size > 0) {
			int itemId;
			itemId = buffer[head];
			head = (head + 1) % 10;
			size = size - 1;
			// consumed itemId (no I/O)
		} else {
			// buffer empty (no I/O)
		}
	}
}

